#!/system/bin/sh
B="${0%/*}/bin/busybox"; F="$@"; [ -f "$F" ]||exit 1; base="${F##*/}"; dir="${F%$base}"; [ -n "$dir" ]||dir="./"; OUT="${dir}${base%.*}_MSAPatcher_Native.txt"; L="$($B unzip -qql "$F" 2>/dev/null|$B sed 's|.* ||g')"; { echo "MSAPatcher 6.2 - Native Inventory"; echo "APK: $base"; echo; echo "== ABI summary =="; echo "$L"|$B grep -E '^lib/.+\.so$'|$B cut -d/ -f2|$B sort|$B uniq -c; echo; echo "== Native libraries =="; echo "$L"|$B grep -E '^lib/.+\.so$'|$B sort; echo; echo "== Notable names =="; echo "$L"|$B grep -Ei '^lib/.+(protect|jiagu|pairip|capstone|bridge|crash|monitor|security|crypto).+\.so$'||echo "none"; echo; echo "Metadata-only inventory; native code is not modified."; } > "$OUT"; cat "$OUT"